CREATE OR REPLACE FUNCTION public.evaluate_farmer_alerts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f record; r record; created_day date; threshold_value numeric; changed integer:=0; BEGIN FOR f IN SELECT owner_id,kind,id,payload FROM public.farmer_records WHERE kind='alert' LOOP BEGIN IF f.payload->>'direction' NOT IN ('above','below') OR f.payload->>'createdAt' IS NULL OR f.payload->>'threshold' IS NULL THEN CONTINUE; END IF; created_day:=((f.payload->>'createdAt')::timestamptz AT TIME ZONE 'Asia/Kolkata')::date; threshold_value:=(f.payload->>'threshold')::numeric; IF threshold_value<=0 OR threshold_value::text IN ('NaN','Infinity','-Infinity') THEN CONTINUE; END IF; SELECT a.date,a.modal_price INTO r FROM public.agri_reports a WHERE a.official AND NOT a.suspicious AND a.price_unit='INR/quintal' AND a.commodity=f.payload->>'crop' AND a.variety=f.payload->>'variety' AND (a.state||'|'||a.district||'|'||a.market)=f.payload->>'marketKey' AND (NOT f.payload ? 'source' OR a.source_name=f.payload->>'source') AND (NOT f.payload ? 'grade' OR COALESCE(a.grade,'')=f.payload->>'grade') AND a.date>=created_day ORDER BY a.date DESC,a.retrieved_at DESC LIMIT 1; IF FOUND THEN UPDATE public.farmer_records SET payload=jsonb_set(payload,'{evaluation}',jsonb_build_object('checkedAt',now(),'reportDate',r.date,'price',r.modal_price,'triggered',CASE WHEN f.payload->>'direction'='above' THEN r.modal_price>=threshold_value ELSE r.modal_price<=threshold_value END,'delivery','in_app_only')) WHERE owner_id=f.owner_id AND kind=f.kind AND id=f.id; changed:=changed+1; END IF; EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN CONTINUE; END; END LOOP; RETURN changed; END $$; REVOKE ALL ON FUNCTION public.evaluate_farmer_alerts() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.evaluate_farmer_alerts() TO service_role; COMMENT ON FUNCTION public.evaluate_farmer_alerts() IS 'Owner-preserving in-app official price evaluation; malformed private payloads cannot interrupt ingestion; optional source and grade enforce snapshot identity.';